-- Generated by generate-bom-seed.py. Invented data: no real company, part, price or quality record.
-- One schema (`bom`) in the shared Postgres, so the pack fits the free edition's three data sources.
CREATE SCHEMA bom;

CREATE TABLE bom.customers (customer_id INT PRIMARY KEY, name VARCHAR(60), region VARCHAR(30));

CREATE TABLE bom.products (product_id INT PRIMARY KEY, customer_id INT REFERENCES bom.customers, sku VARCHAR(20), name VARCHAR(60), category VARCHAR(30), annual_volume INT, target_unit_cost NUMERIC(10,2), required_certification VARCHAR(20), region_restriction VARCHAR(30));

CREATE TABLE bom.assemblies (assembly_id INT PRIMARY KEY, product_id INT REFERENCES bom.products, name VARCHAR(60), parent_assembly_id INT REFERENCES bom.assemblies);

CREATE TABLE bom.materials (material_id INT PRIMARY KEY, name VARCHAR(40), family VARCHAR(30), density_g_cm3 NUMERIC(5,2), cost_per_kg NUMERIC(7,2), yield_strength_mpa INT);

CREATE TABLE bom.processes (process_id INT PRIMARY KEY, name VARCHAR(40), family VARCHAR(30));

CREATE TABLE bom.catalog_items (catalog_item_id INT PRIMARY KEY, sku VARCHAR(20), name VARCHAR(80), shape VARCHAR(20), material_id INT REFERENCES bom.materials, min_tolerance_mm NUMERIC(5,3), max_length_mm INT, max_width_mm INT, max_height_mm INT, finish VARCHAR(20), unit_price NUMERIC(10,2), lead_time_days INT, distributor_certification VARCHAR(20));

CREATE TABLE bom.parts (part_no VARCHAR(12) PRIMARY KEY, name VARCHAR(60), source_type VARCHAR(10), shape VARCHAR(20), material_id INT REFERENCES bom.materials, process_id INT REFERENCES bom.processes, is_critical BOOLEAN, tolerance_mm NUMERIC(5,3), finish VARCHAR(20), length_mm INT, width_mm INT, height_mm INT, catalog_item_id INT REFERENCES bom.catalog_items);

CREATE TABLE bom.bom_lines (bom_line_id INT PRIMARY KEY, assembly_id INT REFERENCES bom.assemblies, part_no VARCHAR(12) REFERENCES bom.parts, quantity INT);

CREATE TABLE bom.suppliers (supplier_id INT PRIMARY KEY, name VARCHAR(60), tier VARCHAR(20));

CREATE TABLE bom.facilities (facility_id INT PRIMARY KEY, supplier_id INT REFERENCES bom.suppliers, name VARCHAR(60), city VARCHAR(40), country VARCHAR(30), region VARCHAR(30), utilization_pct INT, status VARCHAR(20));

CREATE TABLE bom.certifications (certification_id INT PRIMARY KEY, code VARCHAR(20), description VARCHAR(120), applies_to VARCHAR(20));

CREATE TABLE bom.facility_certifications (facility_certification_id INT PRIMARY KEY, facility_id INT REFERENCES bom.facilities, certification_id INT REFERENCES bom.certifications, issued_on DATE, expires_on DATE);

CREATE TABLE bom.machines (machine_id INT PRIMARY KEY, facility_id INT REFERENCES bom.facilities, process_id INT REFERENCES bom.processes, name VARCHAR(50), tightest_tolerance_mm NUMERIC(5,3), status VARCHAR(30));

CREATE TABLE bom.quotes (quote_id INT PRIMARY KEY, part_no VARCHAR(12) REFERENCES bom.parts, facility_id INT REFERENCES bom.facilities, process_id INT REFERENCES bom.processes, unit_cost NUMERIC(10,2), tariff_pct NUMERIC(5,2), lead_time_days INT, min_order_qty INT, valid_until DATE, is_current_source BOOLEAN);

CREATE TABLE bom.approved_vendors (approved_vendor_id INT PRIMARY KEY, customer_id INT REFERENCES bom.customers, supplier_id INT REFERENCES bom.suppliers, status VARCHAR(20));

CREATE TABLE bom.work_orders (work_order_id INT PRIMARY KEY, part_no VARCHAR(12) REFERENCES bom.parts, facility_id INT REFERENCES bom.facilities, quantity INT, scrap_quantity INT, status VARCHAR(20), planned_end DATE, actual_end DATE);

CREATE TABLE bom.nonconformances (nonconformance_id INT PRIMARY KEY, work_order_id INT REFERENCES bom.work_orders, part_no VARCHAR(12) REFERENCES bom.parts, facility_id INT REFERENCES bom.facilities, root_cause VARCHAR(40), severity VARCHAR(10), cost NUMERIC(10,2), opened_on DATE, disposition VARCHAR(30));

CREATE TABLE bom.engineering_changes (eco_id INT PRIMARY KEY, part_no VARCHAR(12) REFERENCES bom.parts, change_type VARCHAR(30), status VARCHAR(20), description VARCHAR(200), opened_on DATE);

CREATE TABLE bom.supply_events (event_id INT PRIMARY KEY, facility_id INT REFERENCES bom.facilities, event_type VARCHAR(30), severity VARCHAR(10), status VARCHAR(15), started_on DATE, note VARCHAR(200));

CREATE TABLE bom.purchase_orders (purchase_order_id INT PRIMARY KEY, part_no VARCHAR(12) REFERENCES bom.parts, facility_id INT REFERENCES bom.facilities, quantity INT, unit_cost NUMERIC(10,2), promised_date DATE, received_date DATE);

CREATE TABLE bom.inventory (inventory_id INT PRIMARY KEY, part_no VARCHAR(12) REFERENCES bom.parts, facility_id INT REFERENCES bom.facilities, on_hand INT, safety_stock INT);

CREATE TABLE bom.dfm_findings (finding_id INT PRIMARY KEY, part_no VARCHAR(12) REFERENCES bom.parts, recommendation VARCHAR(200), saving_pct NUMERIC(5,1), performance_impact VARCHAR(40));

-- The app reads as a SELECT-only account, so no question can change the data.
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'omnigate_ro') THEN CREATE ROLE omnigate_ro LOGIN PASSWORD 'omnigate_ro'; END IF; END $$;
GRANT CONNECT ON DATABASE postgres TO omnigate_ro;
GRANT USAGE ON SCHEMA bom TO omnigate_ro;
GRANT SELECT ON ALL TABLES IN SCHEMA bom TO omnigate_ro;
